/** The standard library, opened with `open Std`. */
export const NORN_STD = "// The standard library, written in Norn and opened with `open Std` (spec §8).\n\nlet remind = (who, text, ~at) => {\n  after(at)->wait\n  ask(who, text)->wait\n}\n\nlet decide = (who, question, ~options, ~recommend, ~by) =>\n  switch choose(who, `${question}\\nRecommended: ${recommend->show}. No answer by ${by->show} means the recommendation.`, options, ~by)->wait {\n  | Answered(choice) => choice\n  | NoReply => recommend             // the declared default, and only when nobody replied in time\n  | other => fail(other)\n  }\n\nlet followUp = (who, text, ~within, ~escalateTo) => {\n  let q = ask(who, text)\n  switch q->waitUntil(within) {\n  | Some(reply) => reply\n  | None => q->handOver(escalateTo)->wait\n  }\n}\n\nlet schedule = (~key=\"schedule\", ~every as period, ~on=never(), task) =>\n  every(period)->or(on)->forEach(~key, _ => run(@auto, task)->wait)\n\n// Work that repeats: a round every period counted from a time, and at once when `on` occurs. `who` does it; when\n// that does not end in an answer, `otherwise` is asked the same once, and a round that still fails is reported.\nlet routine = (~key=\"routine\", ~every as period, ~from, ~on=never(), ~who=@auto, ~otherwise, ~by=8h, task) =>\n  every(period, ~from)->or(on)->forEach(~key, _ =>\n    switch run(who, task, ~by)->wait {\n    | Answered(report) => Answered(report)\n    | _ => run(otherwise, task, ~by)->wait\n    })\n\nlet digest = (who, ~every as period) =>\n  schedule(~every=period, `Tell ${who->show} what changed since they last looked; say nothing if nothing changed`)\n\n// Every reply, in the order the requests were given. The requests were made before this is called, so they are open together.\nlet rec all = requests =>\n  switch requests {\n  | [] => []\n  | [request, ...rest] =>\n    let reply = request->wait\n    [reply, ...all(rest)]\n  }\n\n// Cancels every still-open request in the list (already-settled requests are left untouched).\nlet rec cancelAll = requests =>\n  switch requests {\n  | [] => ()\n  | [request, ...rest] =>\n    cancel(request)\n    cancelAll(rest)\n  }\n\n// Waits for every request to settle without short-circuiting on failures, returning all replies in order.\nlet allSettled = requests => all(requests)\n\n// Waits for the first request to settle and cancels the remaining open requests.\nlet race = requests => {\n  let (winner, reply) = first(requests)\n  cancelAll(requests)\n  (winner, reply)\n}\n\nlet rec partitionOpen = (requests, answers) =>\n  switch requests {\n  | [] => ([], answers)\n  | [request, ...rest] =>\n    let (openReqs, acc) = partitionOpen(rest, answers)\n    switch status(request) {\n    | None => ([request, ...openReqs], acc)\n    | Some(Answered(v)) => (openReqs, [v, ...acc])\n    | Some(_) => (openReqs, acc)\n    }\n  }\n\nlet rec hasAtLeast = (items, n) =>\n  if n <= 0 { true }\n  else {\n    switch items {\n    | [] => false\n    | [_, ...rest] => hasAtLeast(rest, n - 1)\n    }\n  }\n\nlet rec quorumLoop = (requests, needed, answers) => {\n  let (openReqs, nextAnswers) = partitionOpen(requests, answers)\n  if hasAtLeast(nextAnswers, needed) {\n    cancelAll(openReqs)\n    nextAnswers\n  } else {\n    switch openReqs {\n    | [] => nextAnswers\n    | _ =>\n      let (winner, reply) = first(openReqs)\n      cancel(winner)\n      ignore(reply)\n      quorumLoop(openReqs, needed, nextAnswers)\n    }\n  }\n}\n\n// Waits until `~needed` requests return `Answered`, then cancels the remaining open requests and returns the collected answers.\nlet quorum = (requests, ~needed) => quorumLoop(requests, needed, [])\n\n// Heterogeneous stream alternation returning `stream<either<'a, 'b>>` (alias for `or`, alongside homogeneous `merge`).\nlet orEither = (a, b) => or(a, b)\n\n// One branch for each thing that has a `kind`, for as long as it has it. A branch begins when the thing\n// starts having the kind and ends, cancelling what it left open, when it stops; the other branches go on.\n// `branch` gets what holds for its thing and reads it with `Holds.sample`, so a changed value reaches the\n// branch's next round without interrupting the one at work.\nlet each = (~key=\"each\", kind, branch) =>\n  Holds.members(kind)->forEach(~key, ~each=Together, ~per=m => m.id, m =>\n    if m.present { branch(Holds.held(kind, m.id)) } else { () })\n";
